INSERT INTO public.devotionals (legacy_id, publication_date, title, reflection, practical_application, category_id, status) VALUES (31, '2026-08-31', 'Concluindo o ciclo', 'O final de um ciclo é sempre o começo de outro.

Quando chegamos ao fim de uma jornada, a tentação é simplesmente seguir em frente para a próxima coisa. Mas é no espaço entre o fim e o novo começo que a sabedoria é forjada.', 'Pense em algo que você terminou recentemente. O que você aprendeu que pode levar para a próxima etapa?', 'c0b1c6e5-d777-4ab8-b03b-091868027912', 'draft');
